package `in`.xroden.flockr.data.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

@Serializable
data class House(
    val id: String,
    val name: String,
    @SerialName("owner_id")
    val ownerId: String,
    @SerialName("address")
    val address: String? = null,
    @SerialName("latitude")
    val latitude: Double? = null,
    @SerialName("longitude")
    val longitude: Double? = null,
    @SerialName("created_at")
    val createdAt: String? = null
)

@Serializable
data class HouseMember(
    val id: String,
    @SerialName("house_id")
    val houseId: String,
    @SerialName("user_id")
    val userId: String,
    @SerialName("joined_at")
    val joinedAt: String
)

@Serializable
data class HouseWithMembers(
    val house: House,
    val members: List<Profile>
)

package `in`.xroden.flockr.data.repository

import `in`.xroden.flockr.data.model.House
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.gotrue.auth
import io.github.jan.supabase.postgrest.from
import io.github.jan.supabase.postgrest.query.Columns
import io.github.jan.supabase.realtime.PostgresAction
import io.github.jan.supabase.realtime.channel
import io.github.jan.supabase.realtime.postgresChangeFlow
import io.github.jan.supabase.realtime.realtime
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class HouseRepository @Inject constructor(
    private val supabase: SupabaseClient
) {
    private val userId: String?
        get() = supabase.auth.currentUserOrNull()?.id

    fun getHousesFlow(): Flow<List<House>> {
        return kotlinx.coroutines.flow.flow {
            // Emit initial value immediately
            android.util.Log.d("HouseRepository", "Emitting initial houses list")
            emit(getHouses())

            // Then listen for realtime updates
            val channel = supabase.realtime.channel("houses_channel")
            channel.postgresChangeFlow<PostgresAction>(schema = "public") {
                table = "houses"
            }.collect {
                android.util.Log.d("HouseRepository", "Realtime update received, fetching houses")
                emit(getHouses())
            }
        }
    }

    suspend fun getHouses(): List<House> {
        return try {
            val currentUserId = userId ?: run {
                android.util.Log.d("HouseRepository", "No user ID, returning empty list")
                return emptyList()
            }

            android.util.Log.d("HouseRepository", "Fetching houses for user: $currentUserId")

            // Query houses where user is a member
            val houseMembers = supabase.from("house_members")
                .select(Columns.list("house_id")) {
                    filter {
                        eq("user_id", currentUserId)
                    }
                }
                .decodeList<Map<String, String>>()

            val houseIds = houseMembers.mapNotNull { it["house_id"] }
            android.util.Log.d("HouseRepository", "User is member of ${houseIds.size} houses: $houseIds")

            if (houseIds.isEmpty()) {
                android.util.Log.d("HouseRepository", "No houses found, returning empty list")
                return emptyList()
            }

            val houses = supabase.from("houses")
                .select(Columns.ALL) {
                    filter {
                        isIn("id", houseIds)
                    }
                }
                .decodeList<House>()

            android.util.Log.d("HouseRepository", "Successfully fetched ${houses.size} houses")
            houses
        } catch (e: Exception) {
            android.util.Log.e("HouseRepository", "Error fetching houses", e)
            emptyList()
        }
    }

    suspend fun getHouseById(houseId: String): House? {
        return try {
            supabase.from("houses")
                .select(Columns.ALL) {
                    filter {
                        eq("id", houseId)
                    }
                }
                .decodeSingle<House>()
        } catch (e: Exception) {
            null
        }
    }

    suspend fun createHouse(
        name: String,
        address: String?,
        latitude: Double?,
        longitude: Double?
    ): Result<House> {
        return try {
            val currentUserId = userId ?: return Result.failure(Exception("No user logged in"))

            android.util.Log.d("HouseRepository", "createHouse called - name='$name', address='$address', latitude=$latitude, longitude=$longitude, userId=$currentUserId")

            val house = supabase.from("houses")
                .insert(
                    mapOf(
                        "name" to name,
                        "owner_id" to currentUserId,
                        "address" to address,
                        "latitude" to latitude,
                        "longitude" to longitude
                    )
                ) {
                    select()
                }
                .decodeSingle<House>()

            android.util.Log.d("HouseRepository", "createHouse success - created house id=${house.id}, name=${house.name}")
            Result.success(house)
        } catch (e: Exception) {
            android.util.Log.e("HouseRepository", "createHouse failed", e)
            Result.failure(e)
        }
    }

    suspend fun updateHouse(
        houseId: String,
        name: String?,
        address: String?,
        latitude: Double?,
        longitude: Double?
    ): Result<Unit> {
        return try {
            val updates = mutableMapOf<String, Any?>()
            name?.let { updates["name"] = it }
            address?.let { updates["address"] = it }
            latitude?.let { updates["latitude"] = it }
            longitude?.let { updates["longitude"] = it }

            supabase.from("houses")
                .update(updates) {
                    filter {
                        eq("id", houseId)
                    }
                }

            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun addMemberToHouse(houseId: String, userId: String): Result<Unit> {
        return try {
            supabase.from("house_members")
                .insert(
                    mapOf(
                        "house_id" to houseId,
                        "user_id" to userId
                    )
                )

            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

package `in`.xroden.flockr.data.repository

import `in`.xroden.flockr.data.model.House
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.gotrue.auth
import io.github.jan.supabase.postgrest.from
import io.github.jan.supabase.postgrest.query.Columns
import io.github.jan.supabase.realtime.PostgresAction
import io.github.jan.supabase.realtime.channel
import io.github.jan.supabase.realtime.postgresChangeFlow
import io.github.jan.supabase.realtime.realtime
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class HouseRepository @Inject constructor(
    private val supabase: SupabaseClient
) {
    private val userId: String?
        get() = supabase.auth.currentUserOrNull()?.id

    fun getHousesFlow(): Flow<List<House>> {
        return kotlinx.coroutines.flow.flow {
            // Emit initial value immediately
            android.util.Log.d("HouseRepository", "Emitting initial houses list")
            emit(getHouses())

            // Then listen for realtime updates
            val channel = supabase.realtime.channel("houses_channel")
            channel.postgresChangeFlow<PostgresAction>(schema = "public") {
                table = "houses"
            }.collect {
                android.util.Log.d("HouseRepository", "Realtime update received, fetching houses")
                emit(getHouses())
            }
        }
    }

    suspend fun getHouses(): List<House> {
        return try {
            val currentUserId = userId ?: run {
                android.util.Log.d("HouseRepository", "No user ID, returning empty list")
                return emptyList()
            }

            android.util.Log.d("HouseRepository", "Fetching houses for user: $currentUserId")

            // Query houses where user is a member
            val houseMembers = supabase.from("house_members")
                .select(Columns.list("house_id")) {
                    filter {
                        eq("user_id", currentUserId)
                    }
                }
                .decodeList<Map<String, String>>()

            val houseIds = houseMembers.mapNotNull { it["house_id"] }
            android.util.Log.d("HouseRepository", "User is member of ${houseIds.size} houses: $houseIds")

            if (houseIds.isEmpty()) {
                android.util.Log.d("HouseRepository", "No houses found, returning empty list")
                return emptyList()
            }

            val houses = supabase.from("houses")
                .select(Columns.ALL) {
                    filter {
                        isIn("id", houseIds)
                    }
                }
                .decodeList<House>()

            android.util.Log.d("HouseRepository", "Successfully fetched ${houses.size} houses")
            houses
        } catch (e: Exception) {
            android.util.Log.e("HouseRepository", "Error fetching houses", e)
            emptyList()
        }
    }

    suspend fun getHouseById(houseId: String): House? {
        return try {
            supabase.from("houses")
                .select(Columns.ALL) {
                    filter {
                        eq("id", houseId)
                    }
                }
                .decodeSingle<House>()
        } catch (e: Exception) {
            null
        }
    }

    suspend fun createHouse(
        name: String,
        address: String?,
        latitude: Double?,
        longitude: Double?
    ): Result<House> {
        return try {
            val currentUserId = userId ?: return Result.failure(Exception("No user logged in"))

            android.util.Log.d("HouseRepository", "createHouse called - name='$name', address='$address', latitude=$latitude, longitude=$longitude, userId=$currentUserId")

            // Prepare insert payloads
            val responseList: List<Map<String, Any?>> = when {
                address != null && latitude != null && longitude != null -> {
                    @kotlinx.serialization.Serializable
                    data class HouseInsertFull(
                        val name: String,
                        val owner_id: String,
                        val address: String,
                        val latitude: Double,
                        val longitude: Double
                    )
                    supabase.from("houses")
                        .insert(HouseInsertFull(name, currentUserId, address, latitude, longitude)) {
                            select()
                        }
                        .decodeList()
                }
                address != null -> {
                    @kotlinx.serialization.Serializable
                    data class HouseInsertWithAddress(
                        val name: String,
                        val owner_id: String,
                        val address: String
                    )
                    supabase.from("houses")
                        .insert(HouseInsertWithAddress(name, currentUserId, address)) {
                            select()
                        }
                        .decodeList()
                }
                else -> {
                    @kotlinx.serialization.Serializable
                    data class HouseInsertBasic(
                        val name: String,
                        val owner_id: String
                    )
                    supabase.from("houses")
                        .insert(HouseInsertBasic(name, currentUserId)) {
                            select()
                        }
                        .decodeList()
                }
            }

            android.util.Log.d("HouseRepository", "Raw insert response rows: ${responseList.size}")
            if (responseList.isEmpty()) {
                android.util.Log.e("HouseRepository", "createHouse: no rows returned from insert")
                return Result.failure(Exception("No rows returned from insert"))
            }

            val row = responseList[0]
            android.util.Log.d("HouseRepository", "createHouse: returned keys = ${row.keys}")

            // Extract fields with tolerant key names (snake_case or camelCase)
            val id = (row["id"] ?: row["ID"] ?: row["Id"])?.toString()
            val returnedName = (row["name"] ?: row["Name"])?.toString() ?: name
            val ownerIdFromRow = (row["owner_id"] ?: row["ownerId"] ?: row["ownerId"])?.toString() ?: currentUserId
            val addr = (row["address"] ?: row["Address"])?.toString()
            val lat = when (val v = row["latitude"] ?: row["Latitude"]) {
                is Number -> v.toDouble()
                is String -> v.toDoubleOrNull()
                else -> null
            }
            val lon = when (val v = row["longitude"] ?: row["Longitude"]) {
                is Number -> v.toDouble()
                is String -> v.toDoubleOrNull()
                else -> null
            }
            val createdAt = (row["created_at"] ?: row["createdAt"])?.toString()

            if (id == null) {
                android.util.Log.e("HouseRepository", "createHouse: returned row missing id: $row")
                return Result.failure(Exception("Insert returned row without id"))
            }

            val house = House(
                id = id,
                name = returnedName,
                ownerId = ownerIdFromRow,
                address = addr,
                latitude = lat,
                longitude = lon,
                createdAt = createdAt
            )

            android.util.Log.d("HouseRepository", "createHouse success - created house id=${house.id}, name=${house.name}, ownerId=${house.ownerId}")
            Result.success(house)
        } catch (e: Exception) {
            android.util.Log.e("HouseRepository", "createHouse failed", e)
            Result.failure(e)
        }
    }

    suspend fun updateHouse(
        houseId: String,
        name: String?,
        address: String?,
        latitude: Double?,
        longitude: Double?
    ): Result<Unit> {
        return try {
            val updates = mutableMapOf<String, Any?>()
            name?.let { updates["name"] = it }
            address?.let { updates["address"] = it }
            latitude?.let { updates["latitude"] = it }
            longitude?.let { updates["longitude"] = it }

            supabase.from("houses")
                .update(updates) {
                    filter {
                        eq("id", houseId)
                    }
                }

            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun addMemberToHouse(houseId: String, userId: String): Result<Unit> {
        return try {
            supabase.from("house_members")
                .insert(
                    mapOf(
                        "house_id" to houseId,
                        "user_id" to userId
                    )
                )

            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

-- Fix for "infinite recursion detected in policy for relation house_members"
-- This completely rewrites the RLS policies to eliminate circular dependencies

-- First, drop ALL existing policies on both tables
DROP POLICY IF EXISTS "Users can view houses they are members of" ON houses;
DROP POLICY IF EXISTS "Users can view houses they own or are members of" ON houses;
DROP POLICY IF EXISTS "House owners can update their houses" ON houses;
DROP POLICY IF EXISTS "Authenticated users can create houses" ON houses;
DROP POLICY IF EXISTS "Users can view members of their houses" ON house_members;
DROP POLICY IF EXISTS "Users can view members of houses they own or are members of" ON house_members;
DROP POLICY IF EXISTS "House owners can add members" ON house_members;
DROP POLICY IF EXISTS "House owners and system can add members" ON house_members;

-- ============================================
-- HOUSES TABLE POLICIES (NO RECURSION)
-- ============================================

-- SELECT: Users can view houses they own (owner_id check only, no house_members lookup)
-- The trigger adds owners as members, so they'll see it through membership after creation
CREATE POLICY "Owners can view their houses"
    ON houses FOR SELECT
    USING (owner_id = auth.uid());

-- INSERT: Authenticated users can create houses (they must be the owner)
CREATE POLICY "Users can create houses"
    ON houses FOR INSERT
    WITH CHECK (auth.uid() = owner_id);

-- UPDATE: House owners can update their houses
CREATE POLICY "Owners can update their houses"
    ON houses FOR UPDATE
    USING (owner_id = auth.uid());

-- ============================================
-- HOUSE MEMBERS TABLE POLICIES (NO RECURSION)
-- ============================================

-- SELECT: Users can view house_members records where they are the member OR the owner
CREATE POLICY "Users can view house members"
    ON house_members FOR SELECT
    USING (
        user_id = auth.uid()
        OR
        house_id IN (SELECT id FROM houses WHERE owner_id = auth.uid())
    );

-- INSERT: Allow house owners to add members AND allow the trigger to add the owner
-- The trigger runs with SECURITY DEFINER so it bypasses RLS, but we keep this policy for manual adds
CREATE POLICY "Owners can add house members"
    ON house_members FOR INSERT
    WITH CHECK (
        house_id IN (SELECT id FROM houses WHERE owner_id = auth.uid())
    );

-- DELETE: House owners can remove members
CREATE POLICY "Owners can remove house members"
    ON house_members FOR DELETE
    USING (
        house_id IN (SELECT id FROM houses WHERE owner_id = auth.uid())
    );

-- Fix for "column 'role' of relation 'house_members' does not exist"
-- This drops and recreates the trigger without the role column

-- Drop the existing trigger and function
DROP TRIGGER IF EXISTS on_house_created ON houses;
DROP FUNCTION IF EXISTS add_owner_as_member();

-- Recreate the function correctly (without role column)
CREATE OR REPLACE FUNCTION add_owner_as_member()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    INSERT INTO house_members (house_id, user_id)
    VALUES (NEW.id, NEW.owner_id);
    RETURN NEW;
END;
$$;

-- Recreate the trigger
CREATE TRIGGER on_house_created
    AFTER INSERT ON houses
    FOR EACH ROW
    EXECUTE FUNCTION add_owner_as_member();

-- Fix for "Database error saving new user" issue
-- This updates the handle_new_user trigger to properly bypass RLS

-- Drop the existing trigger and function
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
DROP FUNCTION IF EXISTS handle_new_user();

-- Recreate the function with proper RLS bypass
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER -- This runs with elevated privileges
SET search_path = public
AS $$
BEGIN
    INSERT INTO public.profiles (id, email, full_name)
    VALUES (
        NEW.id,
        NEW.email,
        COALESCE(NEW.raw_user_meta_data->>'full_name', '')
    );
    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Log the error but don't fail user creation
        RAISE WARNING 'Error creating profile for user %: %', NEW.id, SQLERRM;
        RETURN NEW;
END;
$$;

-- Recreate the trigger
CREATE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW
    EXECUTE FUNCTION handle_new_user();

-- Grant necessary permissions to the function
GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO postgres, anon, authenticated, service_role;

-- Verify the RLS policy allows service_role to insert
-- The SECURITY DEFINER function should run with the creator's privileges
ALTER TABLE profiles FORCE ROW LEVEL SECURITY;
